export class SelectionLedger {
  private selected: string[] = [];

  replace(candidates: readonly string[]): readonly string[] {
    const normalized = candidates.map((candidate) => candidate.trim());
    if (normalized.some((candidate) => candidate.length === 0)) {
      throw new TypeError("candidates must not contain empty values");
    }

    const next: string[] = [];
    const seen = new Set<string>();
    for (const candidate of normalized) {
      if (!seen.has(candidate)) {
        seen.add(candidate);
        next.unshift(candidate);
      }
    }
    this.selected = next;
    return [...this.selected];
  }

  values(): readonly string[] {
    return [...this.selected];
  }

  drain(): readonly string[] {
    const snapshot = [...this.selected];
    this.selected = [];
    return snapshot;
  }
}

