import { SelectionLedger } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function deepEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

function expectTypeError(fn: () => unknown, message: string): void {
  let error: unknown;
  try {
    fn();
  } catch (caught) {
    error = caught;
  }
  assert(error instanceof TypeError, message);
}

const ledger = new SelectionLedger();
deepEqual(ledger.values(), [], 'constructor must start empty');

const input = [' alpha ', 'beta', 'alpha', ' beta ', 'gamma'];
const inputSnapshot = input.slice();
const replaced = ledger.replace(input);
deepEqual(replaced, ['alpha', 'beta', 'gamma'], 'replace must trim and deduplicate in first-occurrence order');
deepEqual(input, inputSnapshot, 'replace must not mutate its input');

(replaced as string[]).push('injected');
deepEqual(ledger.values(), ['alpha', 'beta', 'gamma'], 'mutating a returned replacement snapshot must not affect the ledger');

const valuesA = ledger.values();
const valuesB = ledger.values();
assert(valuesA !== valuesB, 'values must return a fresh array each time');
(valuesA as string[])[0] = 'changed';
deepEqual(valuesB, ['alpha', 'beta', 'gamma'], 'snapshots must not alias each other');

expectTypeError(() => ledger.replace(['new', '   ', 'other']), 'any blank trimmed candidate must reject the whole replacement');
deepEqual(ledger.values(), ['alpha', 'beta', 'gamma'], 'failed validation must leave prior selection unchanged');

const drained = ledger.drain();
deepEqual(drained, ['alpha', 'beta', 'gamma'], 'drain must return the previous selection');
deepEqual(ledger.values(), [], 'drain must clear the ledger');
(drained as string[]).push('changed');
deepEqual(ledger.values(), [], 'drained snapshot must not alias ledger state');

const cleared = ledger.replace([]);
deepEqual(cleared, [], 'empty replacement must validly clear the ledger');
assert(cleared !== ledger.values(), 'empty snapshots must also be freshly allocated');

